// src/background/index.ts

// Import JSZip and TurndownService statically; assign to global to skip dynamic loading
import JSZip from 'jszip';
import TurndownService from 'turndown';
;(self as any).JSZip = JSZip;
;(self as any).TurndownService = TurndownService;

// Import background-safe checkers from the new utils file
import { isChatSite, isGitHubRepoPage, isGeneralSite } from '../utils/site_checkers.js';
// Import markdown converter utility and content exporters
import { convertHtmlToMarkdown } from '../utils/markdown_converter.js';
import { extractChatData } from '../modules/chat_exporter.js';
import { extractPageData } from '../modules/general_exporter.js';

const api = chrome;

// --- Type Definitions ---
interface GitHubFileItem { path: string; type: 'file' | 'dir'; name: string; }
interface RepoInfo { owner: string; repo: string; ref: string; path: string; apiPath: string; }
interface BackgroundMessage {
    action: 'downloadFile' | 'createAndDownloadZip' | 'getSiteData' | 'runExtraction' | 'fetchGitHubData';
    url?: string;
    filename?: string;
    filesToFetch?: GitHubFileItem[];
    repoInfo?: RepoInfo;
    saveAs?: boolean;
    extractionType?: 'chat' | 'general'; // For runExtraction
    format?: 'txt' | 'md' | 'json' | 'pdf'; // For runExtraction
}
// Define the expected structure of the data extracted by content scripts
interface ExtractedContentData {
    content: string;
    filename?: string;
    error?: string;
    requiresMarkdownConversion?: boolean;
}
interface BackgroundResponse {
    success: boolean;
    error?: string;
    downloadId?: number;
    siteType?: 'chat' | 'github' | 'general' | 'unsupported';
    // Use the specific extracted data type here
    extractedData?: ExtractedContentData;
    githubTreeData?: GitHubFileItem[];
    url?: string;
}
// --- End Type Definitions ---

// JSZip and TurndownService are available via static imports; dynamic loading removed

async function loadJSZip(): Promise<void> {
    // No-op; JSZip is available via static import
    return;
}

async function loadTurndown(): Promise<void> {
    // No-op; TurndownService is available via static import
    return;
}


// --- Message Listener (from popup script) ---
api.runtime.onMessage.addListener((message: BackgroundMessage, sender: chrome.runtime.MessageSender, sendResponse: (response: BackgroundResponse) => void): boolean => {
    const action = message.action;
    console.log("Snaggle BG received message:", action, message);

    (async () => {
        try {
            // --- Get Site Data Request ---
            if (action === 'getSiteData') {
                const tab = await getCurrentTab();
                const url = tab.url!;

                let siteType: BackgroundResponse['siteType'] = 'unsupported';
                if (isChatSite(url)) { siteType = 'chat'; }
                else if (isGitHubRepoPage(url)) { siteType = 'github'; }
                else if (isGeneralSite(url)) { siteType = 'general'; }

                console.log(`Snaggle BG: Site type for ${url} is ${siteType}`);
                sendResponse({ success: true, siteType: siteType, url: url });
            }

            // --- Run Extraction Request ---
            else if (action === 'runExtraction') {
                if (!message.extractionType || !message.format) {
                    throw new Error("Missing extraction type or format.");
                }
                const tab = await getCurrentTab();
                const tabId = tab.id!;
                const format = message.format;

                let functionToInject: (...args: any[]) => ExtractedContentData;

                if (message.extractionType === 'chat') {
                    functionToInject = extractChatData;
                } else if (message.extractionType === 'general') {
                    functionToInject = extractPageData;
                } else {
                    throw new Error(`Unsupported extraction type: ${message.extractionType}`);
                }

                console.log(`Snaggle BG: Executing script for ${message.extractionType} (${format}) in tab ${tabId}`);
                // *** FIX: Remove generic parameter from InjectionResult type ***
                let results: chrome.scripting.InjectionResult[];
                try {
                    results = await api.scripting.executeScript({
                        target: { tabId: tabId },
                        func: functionToInject,
                        // For PDF, extract HTML (as 'md') instead of invoking print dialog
                        args: [format === 'pdf' ? 'md' : format],
                        world: 'ISOLATED'
                    });
                } catch (e: any) {
                    throw new Error(`Script injection failed: ${e.message}`);
                }

                if (!results || results.length === 0 || !results[0]) {
                     throw new Error("Extraction script injection returned no results.");
                }

                 // Cast the result, assuming the injected function returns ExtractedContentData
                 const resultData = results[0].result as ExtractedContentData | undefined;

                 if (!resultData) {
                      throw new Error("Extraction script result is missing or undefined.");
                 }
                 // Check for errors reported *by* the injected script itself
                 if (resultData.error && !resultData.content) {
                     throw new Error(`Extraction script failed: ${resultData.error}`);
                 }
                 // Content might be legitimately empty, but check if it's expected
                 if (typeof resultData.content === 'undefined' && format !== 'pdf') {
                      throw new Error("Extraction script returned undefined content.");
                 }

                let extractedData = resultData as ExtractedContentData; // Now safer to assert

                console.log("Snaggle BG: Raw extraction result:", extractedData);

                if ((format === 'md') && extractedData?.requiresMarkdownConversion && extractedData?.content) {
                    console.log("Snaggle BG: Performing Markdown conversion...");
                    await loadTurndown();
                    extractedData.content = convertHtmlToMarkdown(extractedData.content);
                    extractedData.requiresMarkdownConversion = false;
                }

                // Add default filename if missing
                if (!extractedData.filename) {
                   const dateStr = new Date().toISOString().replace(/[:.]/g, '-');
                   let baseName = "export";
                   try {
                       const urlObject = new URL(tab.url || 'http://unknown.com');
                       baseName = urlObject.hostname.replace(/^www\./, '').split('.')[0] || baseName;
                       if (urlObject.protocol === 'file:') {
                           baseName = urlObject.pathname.split('/').pop()?.split('.')[0] || 'file-export';
                       }
                   } catch { /* ignore URL parsing errors */ }
                   extractedData.filename = `${baseName}-${message.extractionType}-${dateStr}.${format}`;
                }
                console.log("Snaggle BG: Sending successful extraction data to popup");
                // Send the correctly typed data
                sendResponse({ success: true, extractedData: extractedData });
            }

            // --- Fetch GitHub Data ---
            else if (action === 'fetchGitHubData') {
                // ... (GitHub fetch logic remains the same)
                if (!message.repoInfo) {
                    throw new Error("Missing repoInfo for GitHub fetch.");
                }
                const { owner, repo, ref, apiPath = '' } = message.repoInfo;
                const cleanApiPath = apiPath.startsWith('/') ? apiPath.substring(1) : apiPath;
                const apiUrl = `${GITHUB_API_BASE}${owner}/${repo}/contents/${cleanApiPath}?ref=${ref}`;
                console.log("Snaggle BG: Fetching GitHub tree from API:", apiUrl);

                const response = await fetch(apiUrl, { headers: { 'Accept': 'application/vnd.github.v3+json' } });

                if (!response.ok) {
                    let errorMsg = `GitHub API Error: ${response.status} ${response.statusText}`;
                    try {
                        const errData = await response.json();
                        if (errData?.message) errorMsg += ` - ${errData.message}`;
                        if (response.status === 404) errorMsg = `Repo, branch, or path not found ('${cleanApiPath || 'root'}'). Check URL/permissions.`;
                        if (response.status === 403) errorMsg = `Access denied (Rate limit? Private repo?). Check token/permissions.`;
                    } catch { /* Ignore JSON parsing error on error response */ }
                    throw new Error(errorMsg);
                }

                const data: any | any[] = await response.json();
                let itemsToProcess: any[];
                if (!Array.isArray(data)) {
                    if (typeof data === 'object' && data !== null && data.type === 'file') itemsToProcess = [data];
                    else throw new Error("Unexpected GitHub API response format (expected array or single file).");
                } else itemsToProcess = data;

                const files: GitHubFileItem[] = itemsToProcess
                     .map(item => {
                         const mappedItem = {
                             name: item.name,
                             path: item.path,
                             type: (item.type === 'dir') ? 'dir' : 'file'
                         };
                         if (item.type === 'file' || item.type === 'dir') {
                             return mappedItem as GitHubFileItem;
                         }
                         console.warn(`Snaggle BG: Filtering out GitHub item with unexpected type '${item.type}':`, item.path);
                         return null;
                     })
                     .filter((item): item is GitHubFileItem => item !== null)
                     .sort((a, b): number => {
                         const typeOrder = { 'dir': 0, 'file': 1 };
                         const typeA = typeOrder[a.type as 'dir' | 'file'];
                         const typeB = typeOrder[b.type as 'dir' | 'file'];
                         if (typeA !== typeB) return typeA - typeB;
                         return (a.name ?? "").localeCompare(b.name ?? "", undefined, { sensitivity: 'base' });
                     });

                 console.log("Snaggle BG: Sending GitHub tree data to popup");
                 sendResponse({ success: true, githubTreeData: files });
            }

            // --- Download File Request ---
            else if (action === "downloadFile") {
                // ... (Download file logic remains the same, using try/catch)
                if (!message.url || !message.filename) {
                    throw new Error("Missing URL or filename for downloadFile.");
                }
                const allowedSchemes = ['blob:', 'data:', 'http:', 'https:'];
                const urlScheme = message.url.substring(0, message.url.indexOf(':') + 1);
                if (!allowedSchemes.includes(urlScheme)) {
                    throw new Error(`Invalid URL scheme for download: ${urlScheme}`);
                }
                const downloadOptions: chrome.downloads.DownloadOptions = {
                    url: message.url,
                    filename: message.filename,
                    saveAs: message.saveAs ?? true
                };

                let downloadId: number | undefined;
                try {
                    downloadId = await api.downloads.download(downloadOptions);
                } catch (e: any) {
                     throw new Error(`Download initiation failed: ${e.message}`);
                }

                if (downloadId === undefined || downloadId === 0) {
                    throw new Error("Download initiation failed (invalid ID returned or zero).");
                }
                console.log(`Snaggle BG: Download started: ${downloadId}`);
                sendResponse({ success: true, downloadId: downloadId });
            }

            // --- Create and Download ZIP Request ---
            else if (action === "createAndDownloadZip") {
                // ... (ZIP logic remains the same, using try/catch)
                await loadJSZip();
                if (typeof JSZip === 'undefined') {
                    throw new Error("JSZip library not loaded for ZIP creation.");
                }
                if (!message.filesToFetch || !message.repoInfo) {
                    throw new Error("Missing filesToFetch or repoInfo for ZIP.");
                }
                console.log("Snaggle BG: Starting ZIP creation process...");
                const blob = await createZip(message.filesToFetch, message.repoInfo, message.filename || 'github-download.zip');

                console.log("Snaggle BG: ZIP Blob created, size:", blob.size);
                const blobUrl = URL.createObjectURL(blob);
                let downloadId : number | undefined;
                try {
                    const downloadOptions: chrome.downloads.DownloadOptions = {
                        url: blobUrl,
                        filename: message.filename || 'github-download.zip',
                        saveAs: true
                    };
                    try {
                         downloadId = await api.downloads.download(downloadOptions);
                    } catch (e: any) {
                         URL.revokeObjectURL(blobUrl);
                         throw new Error(`ZIP Download initiation failed: ${e.message}`);
                    }
                } finally {
                    setTimeout(() => {
                        console.log("Snaggle BG: Revoking ZIP blob URL:", blobUrl);
                        URL.revokeObjectURL(blobUrl);
                    }, 15000);
                }

                if (downloadId === undefined || downloadId === 0) {
                    throw new Error("ZIP Download initiation failed (invalid ID returned or zero).");
                }
                console.log(`Snaggle BG: ZIP Download started: ${downloadId}`);
                sendResponse({ success: true, downloadId: downloadId });
            }

            // --- Unhandled Action ---
            else {
                 console.warn("Snaggle BG: Unhandled message action:", action);
                 sendResponse({ success: false, error: `Unhandled action: ${action}` });
            }
        } catch (error: any) {
            console.error(`Snaggle BG: Error processing action "${action}":`, error);
            sendResponse({ success: false, error: error.message || "An unknown background error occurred." });
        }
    })();

    return true;
});


// --- Helper Functions ---
async function getCurrentTab(): Promise<chrome.tabs.Tab> {
    // ... (getCurrentTab implementation remains the same, using try/catch)
    let tabs: chrome.tabs.Tab[];
    try {
        tabs = await api.tabs.query({ active: true, currentWindow: true });
    } catch (e: any) {
        console.warn(`Error querying active tab in current window: ${e.message}. Trying last focused window.`);
        tabs = [];
    }

    let tab = tabs?.[0];

    if (!tab) {
        console.log("Snaggle BG: No active tab in current window, trying last focused window.");
        try {
            tabs = await api.tabs.query({ active: true, lastFocusedWindow: true });
        } catch (e: any) {
             throw new Error(`Could not get active tab: ${e.message}`);
        }
         tab = tabs?.[0];
    }

    if (!tab) {
        throw new Error("Could not find the active tab in current or last focused window.");
    }
    if (!tab.id) {
        throw new Error("Active tab is missing an ID.");
    }
    if (!tab.url) {
        console.warn("Active tab is missing a complete URL (may be a chrome:// page or new tab):", tab);
        throw new Error("Active tab is missing a URL.");
    }
    return tab;
}


const GITHUB_API_BASE: string = "https://api.github.com/repos/";

// createZip function remains the same
async function createZip(filesToFetch: GitHubFileItem[], repoInfo: RepoInfo, filename: string): Promise<Blob> {
     // ... (createZip implementation remains the same)
     if (typeof JSZip === 'undefined') { throw new Error("JSZip is not available for ZIP creation."); }
     const zip = new JSZip();
     const { owner, repo, ref } = repoInfo;
     console.log(`Snaggle BG: Adding ${filesToFetch.length} items to ZIP for ${owner}/${repo}#${ref}`);

     const results = await Promise.allSettled(filesToFetch.map(async (item) => {
         const itemPath = item.path || '';
         const cleanItemPath = itemPath.startsWith('/') ? itemPath.substring(1) : itemPath;

         if (item.type === 'file') {
             const apiUrl = `${GITHUB_API_BASE}${owner}/${repo}/contents/${cleanItemPath}?ref=${ref}`;
             try {
                  console.log(`Snaggle BG Zip: Fetching file ${cleanItemPath}`);
                 const response = await fetch(apiUrl, { headers: { 'Accept': 'application/vnd.github.raw+json' } });
                 if (!response.ok) {
                     console.warn(`Snaggle BG Zip: Raw fetch failed for ${cleanItemPath} (${response.status}), trying v3.raw...`);
                     const mediaResponse = await fetch(apiUrl, { headers: { 'Accept': 'application/vnd.github.v3.raw' } });
                      if (!mediaResponse.ok) {
                           let errorMsg = `API Error ${mediaResponse.status}`;
                           try { const errText = await mediaResponse.text(); errorMsg += `: ${errText.substring(0, 100)}`; } catch { }
                           throw new Error(`${errorMsg} fetching ${cleanItemPath}`);
                      }
                      const content: Blob = await mediaResponse.blob();
                      zip.file(itemPath, content, { binary: true });
                      console.log(`Snaggle BG Zip: Added file ${itemPath} (${content.size} bytes) via fallback`);
                 } else {
                     const content: Blob = await response.blob();
                     zip.file(itemPath, content, { binary: true });
                     console.log(`Snaggle BG Zip: Added file ${itemPath} (${content.size} bytes)`);
                 }
                 return { status: 'fulfilled', path: itemPath };
             } catch (error: any) {
                 console.error(`Snaggle BG Zip: Failed file ${itemPath}:`, error);
                 zip.file(itemPath + ".error.txt", `Failed to fetch '${itemPath}':\n${error.message}\nAPI URL: ${apiUrl}`);
                 return Promise.reject({ path: itemPath, reason: error.message });
             }
         } else if (item.type === 'dir') {
             zip.folder(itemPath);
             console.log(`Snaggle BG Zip: Added folder ${itemPath}`);
             return { status: 'fulfilled', path: itemPath };
         } else {
             console.warn(`Snaggle BG Zip: Skipping unknown item type '${item.type}' for path '${itemPath}'`);
             return { status: 'fulfilled', path: itemPath, skipped: true };
         }
     }));

     const failedItems = results.filter(r => r.status === 'rejected');
     if (failedItems.length > 0) {
        console.error(`Snaggle BG Zip: ${failedItems.length} item(s) failed during ZIP creation.`);
        failedItems.forEach(result => {
            if (result.status === 'rejected') {
                const failedInfo = result.reason as { path?: string; reason?: string } | string;
                const path = typeof failedInfo === 'object' ? failedInfo.path : 'unknown path';
                const reason = typeof failedInfo === 'object' ? failedInfo.reason : failedInfo;
                console.error(` - Failed: ${path}, Reason: ${reason}`);
            }
        });
     } else {
         console.log("Snaggle BG Zip: All selected items processed for ZIP.");
     }

     console.log("Snaggle BG: Generating final ZIP blob...");
     return zip.generateAsync({
         type: "blob",
         compression: "DEFLATE",
         compressionOptions: { level: 6 }
     });
 }

console.log("Snaggle Background Service Worker Loaded");

// src/content/extractGeneralData.ts

interface PageExtractionResult {
    content: string;
    error?: string;
    requiresMarkdownConversion?: boolean;
  }

  /**
   * Runs inside the target page and returns extracted content.
   */
  export function extractDataForInjection(): PageExtractionResult {
    const format = 'md'; // hard‑coded for now

    try {
      if (!document.body) throw new Error('Document body not found.');

      let content = '';
      let requiresMarkdownConversion = false;

      // Always use “md” path
      const source =
        document.querySelector('main') ||
        document.querySelector('article') ||
        document.querySelector('[role="main"]') ||
        document.body;

      if (!source) throw new Error('Main content element not found.');

      const clone = source.cloneNode(true) as Element;
      const removeSel = [
        'script',
        'style',
        'link',
        'meta',
        'noscript',
        'svg',
        'iframe',
        'header',
        'footer',
        'nav',
        'aside',
        '[role="banner"]',
        '[role="contentinfo"]',
        '[role="navigation"]',
        '[role="complementary"]',
        'button',
        'input',
        'select',
        'textarea',
        '.advertisement',
        '.ad',
        '#ad',
        '[class*="banner"]',
        '.popup',
        '.modal',
        '#cookie-notice',
        '.cookie-consent'
      ];

      clone.querySelectorAll(removeSel.join(',')).forEach((el) => el.remove());

      content = clone.innerHTML.trim();
      requiresMarkdownConversion = true;

      return { content, requiresMarkdownConversion };
    } catch (err: any) {
      return {
        content: '',
        error: `Failed to extract page data: ${err?.message ?? 'Unknown error'}`
      };
    }
  }

// src/modules/chat_exporter.ts

// Interfaces for structure (can be shared)
interface ChatMessage {
    role: string;
    content: string;
    timestamp: string | null;
  }

  interface ChatExtractionResult {
    content: string;
    filename: string;
    error?: string;
    requiresMarkdownConversion?: boolean;
  }

  // isChatSite function removed - it's now in src/utils/site_checkers.ts

  // This function is intended to be run IN THE PAGE via scripting.executeScript
  export function extractChatData(format: 'txt' | 'md' | 'json'): ChatExtractionResult {
    // --- Site-Specific Selectors --- KEEP YOUR SELECTORS HERE
    const selectors: { [key: string]: any } = {
        // ChatGPT (chat.openai.com) support: extract each message group and its content
        "chat.openai.com": {
            container: 'main', // Main area containing the chat
            messageTurn: 'div[data-testid^="conversation-turn-"]', // More specific selector for turns
            messageContent: 'div.prose', // Content within the turn
            roleIndicator: null, // Role is often implicit or needs parent inspection
            roleAttribute: null, // No direct attribute usually
            timestampSelector: null, // No reliable timestamp selector usually
            // Function to determine role based on turn element (example)
            getRole: (turnElement: Element): string => {
                // Look for specific classes or structures indicating user vs assistant
                // This might need adjustment based on current ChatGPT structure
                const userIcon = turnElement.querySelector('img[alt="User"]'); // Or similar identifier
                if (userIcon) return 'user';
                // Check for assistant indicators
                const assistantProse = turnElement.querySelector('.markdown.prose');
                if(assistantProse) return 'assistant';
                return 'unknown'; // Default
            }
        },
        "gemini.google.com": {
            container: 'main', // Or a more specific chat container if available
            messageTurn: '.message', // Or '.query-container', '.candidate-container' etc.
            messageContent: '.content .text, .markdown', // Check for text or markdown content areas
            roleIndicator: '.participant .name', // Or similar for role text
            timestampSelector: null, // Timestamps might be harder to grab reliably
            getRole: (turnElement: Element): string => {
                const roleEl = turnElement.querySelector('.participant .name');
                const roleText = roleEl?.textContent?.trim().toLowerCase();
                if (roleText === 'user' || roleText?.includes('you')) return 'user';
                if (roleText === 'gemini' || roleText?.includes('model')) return 'assistant';
                return 'unknown';
            }
        },
        "aistudio.google.com": {
            container: 'div.chat-container',
            messageTurn: 'div.message-row',
            messageContent: 'div.message-text',
            roleIndicator: 'div.sender-role',
            timestampSelector: null, // Timestamps not obviously available
            getRole: (turnElement: Element): string => {
                const roleEl = turnElement.querySelector('div.sender-role');
                const roleText = roleEl?.textContent?.trim().toLowerCase();
                if (roleText === 'user') return 'user';
                if (roleText === 'model') return 'assistant';
                return 'unknown';
            }
         },
         // Add more site configurations here
    };

    let extractedContent: string = "";
    let filename: string = "chat-export";
    // ***** Get hostname *inside* the function *****
    let hostname: string = "unknown-host";
    try {
        // Check if running in a context where window is defined (content script)
        if (typeof window !== 'undefined' && window.location) {
           hostname = window.location.hostname;
        } else {
           // Cannot determine hostname if window is not available (should not happen if injected)
           throw new Error("window.location is not accessible in this context.");
        }
    } catch (e: any) {
         console.error("Snaggle extractChatData: Failed to get window.location.hostname", e);
         return { content: "", filename: "error.txt", error: `Could not determine hostname: ${e.message}` };
    }

    const siteConfig = selectors[hostname];
    let requiresMarkdownConversion: boolean = false;

    if (!siteConfig) {
        return { content: "", filename: "error.txt", error: `No selectors defined for ${hostname}. Needs configuration.` };
    }

    try {
        const chatContainer: Element | null = siteConfig.container ? document.querySelector(siteConfig.container) : document.body;
        if (!chatContainer) throw new Error(`Chat container ('${siteConfig.container || 'body'}') not found.`);

        const turns: NodeListOf<Element> = chatContainer.querySelectorAll(siteConfig.messageTurn);
        if (!turns || turns.length === 0) {
             // Fallback if no turns found
             const hasContent = chatContainer.textContent && chatContainer.textContent.trim().length > 50; // Heuristic
             if(hasContent) {
                  console.warn(`Snaggle: No chat turns found using selector: "${siteConfig.messageTurn}", but container has content. Falling back to container's content.`);
                  if (format === 'md') {
                      extractedContent = (chatContainer as HTMLElement).innerHTML.trim();
                      requiresMarkdownConversion = true; // Needs conversion
                  } else { // txt or json (treat json as txt here as structure is lost)
                      extractedContent = (chatContainer as HTMLElement).innerText.trim();
                  }
             } else {
                 throw new Error(`No chat turns found using selector: "${siteConfig.messageTurn}". Site structure may have changed.`);
             }
        }

        const chatData: ChatMessage[] = []; // Use interface

        // Only loop if we didn't use the fallback above
        if (extractedContent === "") {
          turns.forEach((turn: Element, index: number) => {
              let role: string = "unknown";
              let textContent: string = "";
              let timestamp: string | null = null; // Explicitly null

              // --- Extract Role using config ---
              if (siteConfig.getRole && typeof siteConfig.getRole === 'function') {
                  role = siteConfig.getRole(turn);
              } else if (siteConfig.roleIndicator) {
                   const roleIndicatorElement: Element | null = turn.querySelector(siteConfig.roleIndicator);
                   if (roleIndicatorElement) role = roleIndicatorElement.textContent?.trim().toLowerCase() || "unknown";
                   // Standardize role names
                   role = role.replace(/^model$/i, "assistant").replace(/^user$/i, "user");
              } else if (siteConfig.roleAttribute) {
                   role = turn.getAttribute(siteConfig.roleAttribute) || "unknown";
              }


              // --- Extract Timestamp ---
               if (siteConfig.timestampSelector) {
                  const timeElement: Element | null = turn.querySelector(siteConfig.timestampSelector);
                  if (timeElement) {
                      timestamp = siteConfig.timestampAttribute ? timeElement.getAttribute(siteConfig.timestampAttribute) : timeElement.textContent;
                      timestamp = timestamp ? timestamp.trim() : null;
                  }
               }

              // --- Extract Content ---
              const contentElement: HTMLElement | null = turn.querySelector(siteConfig.messageContent);
              if (contentElement) {
                   if (format === 'md') {
                       textContent = contentElement.innerHTML; // Get HTML for potential conversion
                       requiresMarkdownConversion = true;
                   } else {
                       textContent = contentElement.innerText; // Get plain text
                   }
              } else {
                  // If content selector fails, maybe the turn *is* the content?
                  console.warn(`Snaggle: Message content selector ('${siteConfig.messageContent}') failed for turn ${index}, using turn's innerText fallback.`);
                  textContent = (turn as HTMLElement).innerText;
                  if (format === 'md') requiresMarkdownConversion = false; // Can't convert if we only got innerText
              }
              textContent = textContent ? textContent.trim() : "";

              // Skip if no content extracted for this turn
              if (!textContent) {
                  console.log(`Snaggle: Skipping turn ${index} due to empty content.`);
                  return; // Skip this iteration
              }

              // --- Assemble Output ---
              if (format === 'json') {
                  chatData.push({ role, content: textContent, timestamp });
              } else if (format === 'txt') {
                  extractedContent += `Role: ${role}\n`;
                  if (timestamp) extractedContent += `Time: ${timestamp}\n`;
                  extractedContent += `Content:\n${textContent}\n\n---\n\n`;
              } else if (format === 'md') {
                   extractedContent += `**${role.toUpperCase()}**${timestamp ? ` (_${timestamp}_)` : ''}:\n\n`;
                   extractedContent += `${textContent}\n\n`; // Content might be HTML here
                   extractedContent += `***\n\n`;
              }
          });
        } // End if (extractedContent === "") check

        const dateStr: string = new Date().toISOString().replace(/[:.]/g, '-');
        filename = `${hostname.split('.')[0] || 'unknown'}-chat-${dateStr}`;

        if (format === 'json') {
            if (chatData.length > 0) {
                extractedContent = JSON.stringify(chatData, null, 2);
            } else if (extractedContent === "") {
                throw new Error("No chat data or fallback content could be extracted.");
            }
            // If fallback was used, extractedContent holds the text - JSON structure is lost
            filename += '.json';
            requiresMarkdownConversion = false; // JSON never needs markdown conversion
        } else if (format === 'txt') {
            filename += '.txt';
            requiresMarkdownConversion = false; // TXT never needs conversion
        } else if (format === 'md') {
            filename += '.md';
            // Keep requiresMarkdownConversion as determined during extraction
        }

        return {
            content: extractedContent,
            filename: filename,
            requiresMarkdownConversion: format === 'md' && requiresMarkdownConversion // Only MD might need it
        };

    } catch (error: any) {
        console.error("Snaggle Chat Extraction Error:", error);
        return { content: "", filename:"error.txt", error: `Failed to extract chat: ${error?.message ?? 'Unknown error'}` };
    }
  }

// src/modules/general_exporter.ts

// Interface for return type
interface PageExtractionResult {
    content: string;
    error?: string;
    requiresMarkdownConversion?: boolean;
}

// isGeneralSite function removed - it's now in src/utils/site_checkers.ts
// convertHtmlToMarkdown function removed - it's now in src/utils/markdown_converter.ts

// Function executed IN THE CONTEXT OF THE WEBPAGE via scripting.executeScript
export function extractPageData(format: 'txt' | 'md' | 'pdf'): PageExtractionResult {
    console.log(`Snaggle Content Script: extractPageData called with format: ${format}`);
    try {
        let content: string = "";
        let requiresMarkdownConversion: boolean = false;

        // Check if running in a context with 'document'
        if (typeof document === 'undefined' || !document.body) {
            console.error("Snaggle Content Script: document.body is not accessible!");
            throw new Error("Document body not found or not accessible.");
        }

        if (format === 'txt') {
            console.log("Snaggle Content Script: Extracting as TXT using body.innerText");
            // Use optional chaining for safety, although document.body check should cover it
            content = (document.body?.innerText ?? document.documentElement?.innerText ?? "").trim();
             if (!content) {
                 console.warn("Snaggle Content Script: TXT extraction resulted in empty content.");
             }
             requiresMarkdownConversion = false; // TXT format never needs conversion
        } else if (format === 'md' || format === 'pdf') {
             console.log("Snaggle Content Script: Extracting as MD, searching for main content node...");
            // Attempt to find the most relevant content area
            const contentNodeSource: Element | null =
                document.querySelector('main') ||
                document.querySelector('article') ||
                document.querySelector('[role="main"]') ||
                document.body; // Fallback to the entire body

            if (contentNodeSource) {
                 console.log(`Snaggle Content Script: Found content node source: ${contentNodeSource.tagName}${contentNodeSource.id ? '#'+contentNodeSource.id : ''}`);
                 // Clone the node to avoid modifying the live page
                 const contentNode: Node = contentNodeSource.cloneNode(true);
                 console.log("Snaggle Content Script: Cloned content node.");

                 // Selectors for elements to remove from the cloned node
                 const selectorsToRemove: string[] = [
                     'script', 'style', 'link', 'meta', 'noscript', 'svg', 'iframe',
                     'header', 'footer', 'nav', 'aside', '[role="banner"]',
                     '[role="contentinfo"]', '[role="navigation"]', '[role="complementary"]',
                     'button', 'input', 'select', 'textarea', '.advertisement', '.ad',
                     '#ad', '[class*="banner"]', '.popup', '.modal', '#cookie-notice',
                     '.cookie-consent',
                     // Add more selectors for common noise if needed
                     '.sidebar', '#sidebar', '.related-posts', '.comments', '#comments',
                     '.social-share', '.print-button'
                 ];

                 // Ensure contentNode is an Element before using querySelectorAll
                 if (contentNode instanceof Element) {
                    console.log("Snaggle Content Script: Cleaning cloned Element node...");
                    let removedCount = 0;
                    contentNode.querySelectorAll<Element>(selectorsToRemove.join(', '))
                               .forEach((el: Element) => {
                                   el.remove();
                                   removedCount++;
                                });
                    console.log(`Snaggle Content Script: Removed ${removedCount} elements during cleaning.`);

                    // Get the innerHTML of the cleaned node for Markdown conversion
                    content = contentNode.innerHTML.trim();
                    requiresMarkdownConversion = true; // Signal that Turndown conversion is needed
                    console.log(`Snaggle Content Script: Extracted HTML content length: ${content.length}`);

                 } else {
                     // Fallback if the cloned node isn't an element (should be rare)
                     console.warn("Snaggle Content Script: Cloned content node was not an Element. Attempting textContent.");
                     content = contentNode.textContent?.trim() ?? "";
                     requiresMarkdownConversion = false; // No conversion needed for textContent
                     console.log(`Snaggle Content Script: Extracted textContent length: ${content.length}`);
                 }

            } else {
                // This should not happen if document.body exists
                console.error("Snaggle Content Script: Could not identify any content node source (main, article, body).");
                throw new Error("Could not identify page content (body/main/article not found?).");
            }
        } else {
             // Should not be reachable with current background logic
             console.warn(`Snaggle Content Script: Received unexpected format: ${format}`);
             return { content: "", error: `Unsupported format requested: ${format}` };
        }

        // Check if extraction resulted in empty content
        if (!content) {
            console.warn("Snaggle Content Script: Extraction resulted in empty content after processing.");
        }

        console.log("Snaggle Content Script: Extraction successful.");
        return {
            content: content,
            requiresMarkdownConversion: requiresMarkdownConversion
        };

    } catch (error: any) {
        console.error("Snaggle Content Script: Error during extraction:", error);
        return { content: "", error: `Failed to extract page data: ${error?.message ?? 'Unknown error'}` };
    }
}

// src/modules/github_downloader.ts

// Interfaces for structure
export interface RepoInfo { owner: string; repo: string; ref: string; path: string; apiPath: string; }
export interface GitHubFileItem { name: string; path: string; type: 'file' | 'dir'; sha?: string; url?: string; }

// isGitHubRepoPage function removed - it's now in src/utils/site_checkers.ts

/**
 * Parses a GitHub URL to extract repository information.
 * @param urlString The full URL string of the GitHub page.
 * @returns RepoInfo object or throws an error if parsing fails.
 */
export function parseRepoUrl(urlString: string): RepoInfo {
     try {
        const url = new URL(urlString);
        if (url.hostname !== 'github.com') {
            throw new Error("URL is not a github.com URL.");
        }
        const pathParts = url.pathname.split('/').filter(Boolean);
        if (pathParts.length < 2) {
            throw new Error("Invalid GitHub repo URL path (missing owner/repo)");
        }

        const owner: string = pathParts[0];
        const repo: string = pathParts[1];
        let ref: string = 'HEAD'; // Default ref (points to the default branch)
        let currentPath: string = ''; // Path shown in browser URL relative to repo root
        let apiPath: string = ''; // Path used for API 'contents' endpoint (directory path)

        // Determine ref and path based on URL structure (/tree/, /blob/, or root)
        if (pathParts.length > 3 && (pathParts[2] === 'tree' || pathParts[2] === 'blob')) {
            // Structure: /owner/repo/tree|blob/ref/path...
            ref = decodeURIComponent(pathParts[3]);
            currentPath = pathParts.slice(4).map(decodeURIComponent).join('/');
            // API path should be the directory containing the item(s) being viewed
            if (pathParts[2] === 'blob') {
                // If viewing a file, apiPath is the containing directory
                apiPath = currentPath.includes('/') ? currentPath.substring(0, currentPath.lastIndexOf('/')) : '';
            } else {
                 // If viewing a tree, apiPath is the tree path itself
                apiPath = currentPath;
            }
        } else if (pathParts.length > 2) {
            // Structure: /owner/repo/path... (implies default branch)
            // ref remains 'HEAD'
            currentPath = pathParts.slice(2).map(decodeURIComponent).join('/');
            apiPath = currentPath; // Assume path is a directory first

            // Refine apiPath if currentPath looks like a file path
            const fileNamePattern = /\.[^/.]+$/; // Matches a dot followed by non-slashes/dots at the end
             if (apiPath.includes('/') && fileNamePattern.test(pathParts[pathParts.length - 1])) {
                 // File within a directory
                 apiPath = apiPath.substring(0, apiPath.lastIndexOf('/'));
             } else if (!apiPath.includes('/') && fileNamePattern.test(apiPath)) {
                 // File in the root directory
                 apiPath = '';
             }
             // If apiPath ends with a slash, remove it for consistency
             if (apiPath.endsWith('/')) {
                  apiPath = apiPath.slice(0, -1);
             }
        }
        // Ensure apiPath is always a string, default to empty string for root
        apiPath = apiPath || '';

        console.log(`Parsed GitHub URL: owner=${owner}, repo=${repo}, ref=${ref}, path=${currentPath}, apiPath=${apiPath}`);
        return { owner, repo, ref, path: currentPath, apiPath: apiPath };
    } catch (e: any) {
        console.error("Snaggle: Failed to parse GitHub URL:", urlString, e);
        throw new Error(`Could not parse GitHub URL: ${urlString} - ${e?.message ?? 'Unknown reason'}`);
    }
}

// --- UI/Selection Handling Helpers ---
// These functions need access to the popup's DOM and are used by src/popup/index.ts

/** Gets selected file/folder items from the popup's file tree UI. */
export function getSelectedItems(): GitHubFileItem[] {
    const container = document.getElementById('github-file-tree');
    if (!container) {
        console.warn("getSelectedItems: File tree container not found.");
        return [];
    }
    // Select only checked checkboxes that are not the "Select All" checkbox and are not disabled
    const selectedCheckboxes = container.querySelectorAll<HTMLInputElement>(
        'input[type="checkbox"]:checked:not(:disabled):not(#github-select-all)'
    );
    const items: GitHubFileItem[] = [];
    selectedCheckboxes.forEach(checkbox => {
        const type = checkbox.dataset.type;
        const name = checkbox.dataset.name;
        const path = checkbox.value; // The 'value' attribute holds the item's full path
        // Validate required data attributes before adding
        if ((type === 'file' || type === 'dir') && name && path) {
             items.push({ path: path, type: type, name: name });
        } else {
            console.warn("Skipping selected item with missing data:", { value: path, type, name });
        }
    });
    return items;
}

/** Toggles the checked state of all individual file/folder checkboxes in the popup. */
export function toggleSelectAll(checked: boolean): void {
    const container = document.getElementById('github-file-tree');
    const downloadButton = document.getElementById('github-download-zip') as HTMLButtonElement | null;
    if (!container || !downloadButton) return;

    // Select all checkboxes within list items (excluding the main "Select All" one)
    const checkboxes = container.querySelectorAll<HTMLInputElement>(
        'li input[type="checkbox"]:not(:disabled):not(#github-select-all)'
    );
    checkboxes.forEach(checkbox => checkbox.checked = checked);

    // Update the download button's state based on the new selection
    downloadButton.disabled = !checked && checkboxes.length > 0; // Disable if unchecking all
    if (checked && checkboxes.length > 0) {
        downloadButton.disabled = false; // Enable if checking all (and items exist)
    }
}

/** Checks if all individual file/folder checkboxes in the popup are currently selected. */
export function areAllSelected(): boolean {
    const container = document.getElementById('github-file-tree');
    if (!container) return false;

    // Find all checkable items (excluding the main "Select All")
    const allCheckableCheckboxes = container.querySelectorAll<HTMLInputElement>(
        'li input[type="checkbox"]:not(:disabled):not(#github-select-all)'
    );
    if (allCheckableCheckboxes.length === 0) return false; // No items to select

    // Find all *checked* checkable items
    const checkedCheckboxes = container.querySelectorAll<HTMLInputElement>(
        'li input[type="checkbox"]:checked:not(:disabled):not(#github-select-all)'
    );

    // Return true only if the count of all checkable items equals the count of checked items
    return allCheckableCheckboxes.length === checkedCheckboxes.length;
}

